import {stocktakePage,stocktakeDetail,requireStocktakeView} from './stocktake-ui.js';
import {fullProductName} from './product-label.js';
import {icon} from './icons.js';
import {reportQuery,adminReportsPage,adminReportDetail} from './admin-reports-ui.js';
import {workerDashboard,crewRecords} from './team-ui.js';
import {bulkKey,bulkDraft,resetBulkDefaults,saveBulk,bulkReportPage,bulkConfirmation,updateBulkWeight} from './bulk-ui.js';
import {inventoryPage,shipmentEditor,readShipment,stockEditor,adminDates,stockMovements} from './inventory-ui.js';
import {reviewLimit,pendingReviews,pruneReviews,reviewToolbar,reviewCheckbox,syncReviewSelection,reviewConfirmation} from './review-ui.js';
import {wagePanel,wageEditor} from './wages-ui.js';
import {dashboardPage} from './dashboard-ui.js';
import {startCodeCountdown,updateCodeButton} from './login-ui.js';
import {newRequestId} from './request-id.js';
import {enhanceDropdowns,syncDropdowns} from './dropdown.js';
import {importsPage,exportPanel} from './history-ui.js';
import {can,canRead,roleName,manageTabs,allowedPage,defaultPage,navItems,permissionsPage,permissionEditor,adminEditor} from './permissions.js';
import {reportPage,batchInfo,adminFields,historyChanges} from './batch-ui.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n||0).toLocaleString('zh-CN',{maximumFractionDigits:3}),label={pending:'已填写',approved:'已记录',rejected:'已退回'};
const state={token:localStorage.getItem('factory-token'),user:null,boot:null,config:null,page:'home',range:'day',reportCategory:'浇注料',loadingOperation:'装车',filters:{},manage:'users',manageCategory:'',keyword:'',records:[],stats:null,detail:null,history:[],busy:false,batchReview:false,reviewSelection:new Map(),reviewBatch:[],reportBatch:false,stockTab:'shipments',inventoryCategory:'预制块',stockVisible:30,stockKeyword:''};
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500);}
async function api(url,options={}){const res=await fetch('/api'+url,{...options,headers:{'Content-Type':'application/json',...(state.token?{Authorization:'Bearer '+state.token}:{}),...options.headers},body:options.body?JSON.stringify(options.body):undefined});const json=await res.json();if(!res.ok){if(res.status===401){state.token=null;localStorage.removeItem('factory-token');state.user=null;render();}const error=new Error(json.error||'请求失败');error.status=res.status;throw error;}return json;}
function monthStart(d){return d.slice(0,7)+'-01';}function query(){const d=state.boot?.today||state.config?.today;return new URLSearchParams({from:state.filters.from||(state.range==='month'?monthStart(d):d),to:state.filters.to||d,...Object.fromEntries(Object.entries(state.filters).filter(([k,v])=>v&&k!=='from'&&k!=='to'))}).toString();}
function group(id){return state.boot?.groups.find(g=>g.id===id)?.name||'';}function fmtTime(t){return new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});}
function options(items,value,labelFn=x=>x.name){return items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(labelFn(x))}</option>`).join('');}
function field(title,control){return `<label class="field"><span>${title}</span>${control}</label>`;}function detail(k,v){return `<div class="detail-row"><span>${esc(k)}</span><b>${esc(v)}</b></div>`;}
function draftKey(category=state.reportCategory){return 'draft-'+state.user.id+'-'+category+(category==='装/卸车'?'-'+state.loadingOperation:'');}
function loadingPreference(){try{const saved=localStorage.getItem('loading-operation-'+state.user.id);if(['装车','卸车'].includes(saved))return saved;const old=JSON.parse(localStorage.getItem('draft-'+state.user.id+'-装/卸车')||'null');return old&&old.productId!=='material-73'?'卸车':'装车';}catch{return '装车';}}
function draft(){try{let saved=JSON.parse(localStorage.getItem(draftKey()));if(state.reportCategory==='装/卸车'&&!saved){const legacyKey='draft-'+state.user.id+'-装/卸车',legacy=JSON.parse(localStorage.getItem(legacyKey)||'null'),product=state.boot.products.find(p=>p.id===legacy?.productId);if(legacy&&(product?.loadingOperation||'装车')===state.loadingOperation){saved=legacy;localStorage.setItem(draftKey(),JSON.stringify(saved));localStorage.removeItem(legacyKey);}}const old=JSON.parse(localStorage.getItem('draft-'+state.user.id)),d=saved||(old&&state.boot.products.find(p=>p.id===old.productId)?.category===state.reportCategory?old:{});if(state.reportCategory==='浇注料'&&d.quantity&&d.unitPolicy!=='tons-2-v1'){localStorage.setItem(draftKey()+'-before-tons',JSON.stringify(d));Object.assign(d,{quantity:'',requestId:newRequestId(),unitPolicy:'tons-2-v1',unitChanged:true});localStorage.setItem(draftKey(),JSON.stringify(d));}if(Object.hasOwn(d,'shift')||Object.hasOwn(d,'batchCode'))d.requestId=newRequestId();delete d.shift;delete d.batchCode;delete d.productKeyword;delete d.remark;if(!state.boot.fillDates.includes(d.date))d.date=state.boot.today;return d;}catch{return {};}}
function saveDraft(form){const data=Object.fromEntries(new FormData(form));data.unitPolicy='tons-2-v1';data.workerId=data.workerId||state.user.id;data.mode=state.user.isLeader?'leader':'personal';data.memberIds=[state.user.id];data.entries=[{workerId:data.workerId,quantity:data.quantity}];data.requestId=form.dataset.requestId||newRequestId();localStorage.setItem(draftKey(),JSON.stringify(data));return data;}
async function refresh(){if(!state.token)return;state.boot=await api('/bootstrap');state.user=state.boot.user;if(!allowedPage(state.user,state.page))state.page=defaultPage(state.user);if(state.user.role==='admin'&&state.page==='records'&&state.range==='day')state.range='month';document.documentElement.style.setProperty('--fs',state.user.fontSize+'px');if(state.page==='stocktake'){state.stocktake=await api('/monthly-stocktake');}else if(state.page==='inventory'){await loadStock();}else if(state.page==='home'&&state.user.role==='worker'){state.overview=await api('/production-overview?'+query());state.wages=await api('/wages?'+query());}else if(state.page==='home'){if(can(state.user,'stats')||can(state.user,'salary')){state.adminReport=await api('/admin/reports?'+reportQuery(state));if(!can(state.user,'stats'))state.reportTab='wages';else if(!can(state.user,'salary'))state.reportTab='production';}else state.adminReport=null;}else if(state.page==='records')state.records=(await api('/records?'+query())).records;else if(state.page==='manage')await loadManagement();else if(state.page==='detail'&&state.detail){const r=await api('/records/'+state.detail.id);state.detail=r.record;state.history=r.history;}if(state.page==='records')pruneReviews(state);render();}
async function loadManagement(){const tabs=manageTabs(state.user);if(!tabs.some(t=>t[0]===state.manage))state.manage=tabs[0]?.[0];if(state.manage==='users')state.users=(await api('/users')).users;if(state.manage==='requests')state.requests=(await api('/change-requests')).requests;if(state.manage==='history')state.imports=(await api('/imports')).imports;if(state.manage==='permissions'){state.admins=(await api('/admins')).admins;}}
function businessTabs(action='business',current=state.filters.loadingOperation||state.filters.category||'预制块'){const items=action==='business'?['预制块','浇注料','装车','卸车']:['预制块','浇注料','装/卸车'];return '<div class="tabs business-tabs">'+items.map(value=>'<button data-action="'+action+'" data-value="'+value+'" class="'+(current===value?'active':'')+'">'+(value==='装/卸车'?'装卸车':value)+'</button>').join('')+'</div>';}
function loginView(){return `<div class="card"><div class="login-icon">${icon('phone')}</div><h2>手机号登录</h2><p class="small note">请使用管理员登记的手机号</p><form id="login-form">${field('手机号','<input name="phone" id="phone" type="tel" maxlength="11" autocomplete="tel" inputmode="tel" required placeholder="输入11位手机号">')}<button type="button" class="soft" data-action="send-code">获取验证码</button><p class="small" id="code-help"></p>${field('短信验证码','<input name="code" type="text" inputmode="numeric" maxlength="6" autocomplete="one-time-code" required placeholder="输入6位验证码">')}<button class="primary" type="submit">登录</button></form></div>`;}
function period(){
 const active=[group(state.filters.groupId),state.boot.workers.find(u=>u.id===state.filters.workerId)?.name,label[state.filters.status],state.page==='records'?(state.filters.loadingOperation||state.filters.category):''].filter(Boolean);
 return `<div class="tabs period-tabs" role="group" aria-label="统计日期">${(state.user.role==='admin'?[['month','本月'],['custom','自定义']]:[['day','今日'],['month','本月'],['custom','自定义']]).map(([k,v])=>`<button data-action="period" data-value="${k}" aria-pressed="${state.range===k}" class="${state.range===k?'active':''}">${v}</button>`).join('')}</div><details class="filter-panel" ${state.range==='custom'?'open':''}><summary><span class="filter-summary">筛选${active.length?`<small>${active.map(esc).join(' · ')}</small>`:''}</span></summary><form id="filter-form"><div class="filters">${state.range==='custom'?field('开始日期',`<input type="date" name="from" value="${esc(state.filters.from||state.boot.today)}">`)+field('结束日期',`<input type="date" name="to" value="${esc(state.filters.to||state.boot.today)}">`):''}${state.user.role==='admin'?field('班组',`<select name="groupId"><option value="">全部班组</option>${options(state.boot.groups,state.filters.groupId)}</select>`)+field('工人',`<select name="workerId" data-search="true"><option value="">全部工人</option>${options(state.boot.workers,state.filters.workerId)}</select>`):''}${field('状态',`<select name="status"><option value="">全部状态</option>${Object.entries(label).map(([k,v])=>`<option value="${k}" ${state.filters.status===k?'selected':''}>${v}</option>`).join('')}</select>`)}${state.page==='home'?'':field('分类',`<select name="category"><option value="">全部分类</option>${['预制块','浇注料','装车','卸车'].map(v=>`<option ${(state.filters.loadingOperation||state.filters.category)===v?'selected':''}>${v}</option>`).join('')}</select>`)}</div><button class="soft" type="submit">应用筛选</button></form></details>`;
}
function recordCard(r){const memberOnly=state.user?.role==='worker'&&!state.user?.isLeader;if(memberOnly&&r.excludedReason)return '';const precastWeight=r.product.category==='预制块'?(r.weightKg===null?'单重待设置':num(r.weightKg/1000)+' 吨'):'';return `<article class="card record" data-record-id="${r.id}"><div class="record-head"><b>${esc(fullProductName(r.product))}</b><span class="badge ${r.excludedReason?'replaced':r.status}">${r.excludedReason?'已替换':label[r.status]}</span></div><div class="record-amount"><div><b>${num(r.quantity)}<small>${esc(r.product.unit)}</small></b>${precastWeight?`<p class="small">折合重量 ${esc(precastWeight)}</p>`:''}</div><span class="small">${r.date}</span></div><p class="record-meta">${r.members.map(m=>esc(m.name)).join('、')}${group(r.groupId)?' · '+esc(group(r.groupId)):''}</p>${r.status==='rejected'?`<div class="correction">${esc(r.rejectionReason)}</div>`:''}<div class="record-actions">${!memberOnly?`<button class="soft" data-action="detail" data-id="${r.id}">${can(state.user,'review')?'详情':can(state.user,'edit')?'查看 / 修改':'查看详情'}</button>`:''}${r.canDelete?`<button class="danger" aria-label="删除未确认记录" data-action="delete-record" data-id="${r.id}" data-version="${r.version}">删除</button>`:''}</div></article>`;}
function homeView(){if(state.user.role==='worker')return workerDashboard(state,{esc,num,recordCard,options});return state.adminReport?adminReportsPage(state,{esc,num,options,field}):'<p class="empty">工作权限由总管理员设置</p>';}
function reportView(){if(state.user.isLeader)return bulkReportPage(state,{esc,field,options});return '';}
function detailView(){
 const r=state.detail;if(!r)return '<p class="empty">正在加载</p>';
 const admin=state.user.role==='admin',editAdmin=can(state.user,'edit'),reviewAdmin=can(state.user,'review'),editable=!admin&&state.user.isLeader&&r.submittedBy===state.user.id&&r.status!=='approved';
 const precastWeight=r.product.category==='预制块'?(r.weightKg===null?'单重待设置':num(r.weightKg/1000)+' 吨'):'';
 return `<div class="card record"><div class="record-head"><b>${esc(fullProductName(r.product))}</b><span class="badge ${r.excludedReason?'replaced':r.status}">${r.excludedReason?'已替换':label[r.status]}</span></div><div class="record-amount"><div><b>${num(r.quantity)}<small>${esc(r.product.unit)}</small></b>${precastWeight?`<p class="small">折合重量 ${esc(precastWeight)}</p>`:''}</div><span class="small">${r.date}</span></div><p class="record-meta">${r.members.map(m=>esc(m.name)).join('、')} · ${esc(group(r.groupId))}</p>${r.excludedReason?`<div class="correction">${esc(r.excludedReason)}</div>`:''}${r.status==='rejected'?`<div class="correction">${esc(r.rejectionReason)}</div>`:''}</div>

 ${editAdmin||editable?`<details class="disclosure"><summary>修改填写</summary><div class="disclosure-body"><form id="correction-form">${admin?adminFields(r,state,{esc,field,options}):''}${field('生产量',`<input name="quantity" id="edit-quantity" type="number" min="${admin?0:10**-r.product.precision}" step="${10**-r.product.precision}" value="${r.quantity}" inputmode="decimal" required>`)}<div class="weight"><span>折合重量</span><b id="edit-weight">${r.weightKg===null?'—':num(r.weightKg/1000)+' 吨'}</b></div>${field('修改原因',`<textarea name="reason" rows="2" maxlength="300" placeholder="请输入修改原因" required></textarea>`)}<button class="primary" type="submit">${admin?'保存修改':'重新提交'}</button></form></div></details>`:''}
 ${!admin&&r.status==='approved'?'<button class="soft" data-action="change-request">申请修改 / 提出异议</button>':''}
 <details class="disclosure"><summary>填写信息</summary><div class="disclosure-body">${detail('规格 / 单位',r.product.spec+' / '+r.product.unit)}${detail('填写人',r.submittedName)}${detail('首次填写量',num(r.originalQuantity)+r.originalUnit)}${detail('计入汇总',r.counted?'是':'否')}${batchInfo(r,{esc,num})}</div></details>
 ${state.user.role==='worker'?`<details class="disclosure"><summary>修改历史 · ${state.history.length}次</summary><div class="disclosure-body">${state.history.map(h=>`<div class="history"><b>${esc(historyChanges(h,state,{num}))} ${esc(r.product.unit)}</b><p class="small">${esc(h.actor)} · ${fmtTime(h.time)}</p><p class="small">${esc(h.reason)}</p></div>`).join('')||'<p class="empty">暂无修改记录</p>'}</div></details>`:''}<button class="secondary" data-action="refresh-detail">刷新记录</button><button class="secondary" data-action="navigate" data-page="records">返回记录列表</button>`;
}
function settingsView(){const permissionNames={records:'查看记录',review:'月度盘点',edit:'修改记录',stats:'全厂统计',salary:'查看工资',export:'Excel导出',history:'历史导入',staff:'员工管理',products:'产品管理',shipping:'填写发货清单',inventory:'库存管理'};return `<div class="card settings-account"><div class="profile"><div class="avatar">${esc(state.user.name.slice(0,1))}</div><div><p>${esc(state.user.name)}</p><p class="small">${roleName(state.user)}</p></div></div><p class="small">${esc(state.user.phone)}</p></div>${state.user.role==='admin'?`<details class="disclosure"><summary>我的权限</summary><div class="disclosure-body"><p class="small">${state.user.isSuperAdmin?'总管理员拥有全部权限。':state.user.permissions.length?state.user.permissions.map(p=>permissionNames[p]).join('、'):'暂未分配工作权限，请联系总管理员。'}</p><button class="soft space" data-action="refresh-permissions">刷新权限</button></div></details>`:''}<div class="card"><h2>字体大小</h2><div class="tabs">${[[18,'标准'],[22,'大字'],[26,'特大']].map(([v,n])=>`<button class="${state.user.fontSize===v?'active':''}" data-action="font" data-value="${v}">${n}</button>`).join('')}</div></div><button class="secondary" data-action="logout">退出登录</button>`;}
function manageView(){const tabs='<div class="tabs manage-tabs">'+manageTabs(state.user).map(([id,name])=>'<button data-action="manage-tab" data-value="'+id+'" class="'+(state.manage===id?'active':'')+'">'+name+'</button>').join('')+'</div>';if(state.manage==='permissions')return tabs+permissionsPage(state,{esc,fmtTime});if(state.manage==='history')return tabs+ importsPage(state,{esc,num,field});const type=state.manage,list=(type==='users'?state.users||[]:state.boot.products).filter(x=>(x.name+' '+(x.phone||'')+' '+(x.spec||'')).includes(state.keyword)&&(type!=='products'||!state.manageCategory||x.category===state.manageCategory));return `${tabs}${type==='products'?businessTabs('manage-category',state.manageCategory):''}${type==='requests'?(state.requests||[]).map(r=>`<div class="card"><b>${esc(r.name)}申请修改</b><p class="small space">${esc(r.reason)}</p><button class="soft" data-action="detail" data-id="${r.record_id}">查看生产记录</button><button class="secondary" data-action="resolve-request" data-id="${r.id}">填写处理说明</button></div>`).join('')||'<p class="empty">没有待处理申请</p>':`<button class="primary" data-action="manage-edit">新增${type==='users'?'员工':'产品'}</button><form id="search-form" class="space"><input name="keyword" type="search" value="${esc(state.keyword)}" placeholder="查找${type==='users'?'姓名或手机号':'产品名称或规格'}"><button class="soft" type="submit">查找</button></form><p class="small note">${list.length}条${list.length>80?'，请搜索缩小范围':''}</p><div class="manage-grid">${list.slice(0,80).map(x=>`<div class="card"><div class="record-head"><b>${esc(type==='products'?fullProductName(x):x.name)}</b><span class="badge ${x.active?'':'pending'}">${x.active?'启用':'停用 / 待配置'}</span></div><p class="small">${type==='users'?esc(x.phone||'待绑定手机号')+' · '+roleName(x):esc(x.spec)+' · '+esc(x.unit||'单位待配置')}</p>${!x.isSuperAdmin?`<button class="soft" data-action="manage-edit" data-id="${x.id}">编辑${type==='users'?'员工':'产品'}</button>`:'<p class="small">总管理员账号固定</p>'}</div>`).join('')}</div>`}`;}
function recordsView(){const rows=state.user?.role==='worker'?state.records.filter(r=>!r.excludedReason):state.records;return (state.user.role==='admin'&&(can(state.user,'review')||can(state.user,'inventory'))?'<button class="primary monthly-stocktake-entry" data-action="navigate" data-page="stocktake">月度盘点</button>':'')+period()+'<div class="record-grid">'+(rows.map(recordCard).join('')||'<p class="empty">没有对应的记录</p>')+'</div>'+(can(state.user,'export')?'<details class="disclosure export-tools"><summary>导出原格式月报</summary><div class="disclosure-body">'+exportPanel(state,{field})+'</div></details>':'');}
function render(){const logged=!!state.user,page=logged?state.page:'login',titles={login:'欢迎使用',home:state.user?.role==='admin'?'数据统计':'我的',report:'填写生产',records:'生产记录',stocktake:'月度盘点',detail:'生产详情',settings:'设置',manage:'工厂管理',inventory:'发货与库存'};const nav=navItems(state.user);let content=page==='login'?loginView():page==='home'?homeView():page==='report'?reportView():page==='records'?recordsView():page==='detail'?detailView():page==='manage'?manageView():page==='inventory'?inventoryPage(state,{esc,num,field,options}):page==='stocktake'?stocktakePage(state,{esc,num}):settingsView();$('#app').innerHTML=`<div class="shell role-${state.user?.role||'guest'}"><header class="header"><div class="brand-row"><span class="brand"><span class="brand-mark">${icon('factory')}</span>${esc(state.boot?.factoryName||state.config?.factoryName||'生产记工')}</span></div><div class="title-row"><h1>${titles[page]}</h1>${logged&&page!=='settings'?`<button class="settings-entry" data-action="navigate" data-page="settings" aria-label="进入设置">${icon('settings')}设置</button>`:''}</div><p class="small">${logged?esc(state.user.name)+' · '+(roleName(state.user)):'填写方便，汇总清楚'}</p></header>${logged?`<nav class="nav">${nav.map(([k,v,i])=>`<button class="${state.page===k?'active':''}" data-action="navigate" data-page="${k}"><span class="nav-mark" aria-hidden="true">${icon(k==='home'&&state.user.role==='admin'?'stats':k==='records'&&can(state.user,'review')?'review':k)}</span>${v}</button>`).join('')}</nav>`:''}<main class="body page-${page}">${content}</main></div>`;document.title=(state.boot?.factoryName||state.config?.factoryName||'生产记工')+' · '+titles[page];enhanceDropdowns();syncReviewSelection(state);updateCodeButton(state.busy);if(page==='report')updateReportWeight();}
function updateReportWeight(){const form=$('#report-form');if(!form)return;const p=state.boot.products.find(p=>p.id===form.productId.value),q=Number(form.quantity.value);form.quantity.step=p?10**-p.precision:1;form.quantity.min=form.quantity.step;$('#report-weight').textContent=p&&form.quantity.value!==''?(p.weightKg?num(q*p.weightKg/1000)+' 吨':p.unit==='吨'?num(q)+' 吨':'按 '+p.unit+' 统计'):'—';}
function modal(title,body,buttons){const d=$('#dialog');d.innerHTML=`<h2 tabindex="-1">${esc(title)}</h2>${body}<div class="actions">${buttons}</div>`;enhanceDropdowns(d);d.showModal();d.scrollTop=0;d.querySelector("h2").focus({preventScroll:true});}function closeModal(){if($('#dialog').open)$('#dialog').close();}
async function navigate(page){if(!allowedPage(state.user,page))throw new Error('没有访问该页面的权限');if(page!=='records'){state.batchReview=false;state.reviewSelection.clear();}if(page==='stocktake'&&state.page!=='stocktake'){state.stocktakeStatus='pending';state.stocktakeCategory='';state.stocktakeKeyword='';}state.page=page;await refresh();if(page==='report'&&state.user.isLeader){resetBulkDefaults(state);render();}window.scrollTo(0,0);}
async function login(phone,code){const r=await api('/auth/login',{method:'POST',body:{phone,code}});state.token=r.token;state.user=r.user;localStorage.setItem('factory-token',r.token);state.page=defaultPage(r.user);state.reportCategory=localStorage.getItem('report-module-'+r.user.id)||'浇注料';state.loadingOperation=loadingPreference();state.batchReview=false;state.reviewSelection.clear();state.filters={};state.range=r.user.role==='admin'?'month':'day';state.reportPeriod='day';state.reportDate=null;state.reportGroup='';state.reportTab=can(state.user,'stats')?'production':'wages';await refresh();window.scrollTo(0,0);}

function stockQuery(){const d=state.boot.today;return new URLSearchParams(state.stockRange||{from:d,to:d}).toString();}
async function loadStock(){const [s,l,c]=await Promise.all([api('/inventory?'+stockQuery()),api('/shipments?'+stockQuery()),api('/shipping-customers')]);state.inventory=s;state.shipments=l.shipments;state.shippingCustomers=c.customers;}
function openShipment(d){state.shipmentDraft=d;modal(d?.id?'修改发货清单':'填写发货清单',shipmentEditor(state,d,{esc,field,options}),'<button data-action="close-modal">返回</button>');}
function updateStockSetting(){const form=$('#stock-opening-form')||$('#stock-count-form');if(!form)return;const row=state.inventory.rows.find(r=>r.product.id===form.elements.productId.value),count=form.id==='stock-count-form',p=row?.product;form.dataset.version=count?row?.countVersion||0:row?.initial?.version||0;form.elements.quantity.value=count?row?.physical??'':row?.initial?.quantity??'';form.elements.quantity.step=p?10**-p.precision:1;form.querySelector('.input-unit').textContent=p?.unit||'';if(!count){const selected=row?.initial?.startDate||state.boot.today,select=form.elements.startDate;select.innerHTML=options(adminDates(state.boot.today,selected),selected);select.nextElementSibling?.remove();select.classList.remove('select-source');enhanceDropdowns(form);}}
async function act(action,el){
 if(action==='report-view'){state.reportTab=el.dataset.value;render();}
 if(action==='report-period'){state.reportPeriod=el.dataset.value;await refresh();}
 if(action==='report-date-step'){state.reportDate=el.dataset.value;await refresh();}
 if(action==='report-business'){state.reportBusiness=el.dataset.value;state.reportGroup='';await refresh();}
 if(action==='report-drill'){const q=new URLSearchParams(reportQuery(state));q.set('kind',el.dataset.kind);q.set('id',el.dataset.id);const r=await api('/admin/reports/detail?'+q);modal(r.name+(r.kind==='wage-worker'?'的工资明细':'的生产明细'),adminReportDetail(r,{esc,num}),'<button data-action="close-modal">关闭</button>');}
 if(action==='report-record'){closeModal();await act('detail',el);}
 if(action==='worker-period'){state.range=el.dataset.value;state.filters=state.range==='custom'?{from:monthStart(state.boot.today),to:state.boot.today}:{};await refresh();}
 if(action==='personal-report'){state.reportBatch=false;await navigate('report');}
 if(action==='crew-records'){const q=new URLSearchParams(query());q.set('workerId',el.dataset.id);const business=el.dataset.business;q.set('category',['装车','卸车'].includes(business)?'装/卸车':business);if(['装车','卸车'].includes(business))q.set('loadingOperation',business);const data=await api('/production-overview?'+q),name=state.boot.workers.find(w=>w.id===el.dataset.id)?.name;modal(name+' · '+el.dataset.business,crewRecords(data,{esc,num}),'<button data-action="close-modal">关闭</button>');}
 if(action==='open-bulk-report'){state.reportBatch=true;await navigate('report');}
 if(action==='report-batch'){if($('#report-form'))saveDraft($('#report-form'));if($('#bulk-report-form'))saveBulk(state,$('#bulk-report-form'));state.reportBatch=el.dataset.value==='true';render();}
 if(action==='bulk-add'||action==='bulk-remove'){const d=saveBulk(state,$('#bulk-report-form'));if(action==='bulk-add'){if(d.entries.length>=100)throw new Error('一次最多100行');d.entries.push({workerId:state.boot.workers[0]?.id,productId:state.reportCategory==='装/卸车'&&state.loadingOperation==='装车'?state.boot.products.find(p=>p.active&&p.loadingOperation==='装车')?.id||'':'',quantity:''});}else d.entries.splice(Number(el.dataset.index),1);localStorage.setItem(bulkKey(state),JSON.stringify(d));render();}
 if(action==='submit-bulk-report'){await api('/records/leader',{method:'POST',body:{...state.bulkSubmission,entries:state.bulkSubmission.entries.map(e=>({...e,quantity:Number(e.quantity)}))}});localStorage.removeItem(bulkKey(state));closeModal();toast('已提交，产量和工资已更新');state.bulkSubmission=null;await navigate('report');}
 if(action==='stocktake-status'){state.stocktakeStatus=el.dataset.value;render();}
 if(action==='stocktake-category'){state.stocktakeCategory=el.dataset.value;render();}
 if(action==='stocktake-detail'){const view=el.dataset.view||'previous';state.stocktakeDetail=requireStocktakeView(await api('/monthly-stocktake/'+el.dataset.id+'?view='+encodeURIComponent(view)),view);modal(fullProductName(state.stocktakeDetail.product)+' · '+({previous:'上月盘点明细',month:'当月库存明细',current:'当前剩余库存明细'}[view]),stocktakeDetail(state.stocktakeDetail,{esc,num}),'<button data-action="close-modal">关闭</button>');}
 if(action==='stocktake-mark'){const row=state.stocktake.rows.find(r=>r.product.id===el.dataset.id);try{const result=await api('/monthly-stocktake/'+row.product.id,{method:'PUT',body:{month:state.stocktake.month,status:el.dataset.value,version:row.reviewVersion,fingerprint:row.fingerprint}});toast(el.dataset.value==='confirmed'?(result.confirmedRecords?'盘点及对应生产记录已确认':'盘点已确认'):'已标记错误');}finally{await refresh();}}
 if(action==='stocktake-reopen'){const data=state.stocktakeDetail;try{await api('/monthly-stocktake/'+data.product.id+'/reopen',{method:'POST',body:{month:data.month,version:data.review.reviewVersion,fingerprint:data.review.fingerprint}});state.stocktakeStatus='pending';toast('已移回待盘点');}finally{closeModal();await refresh();}}
 if(action==='pump-camera'||action==='pump-choose')document.getElementById(action).click();
 if(action==='pump-remove'){const form=$('#shipment-form');form.elements.pumpFileId.value='';$('#pump-file-info').textContent='未上传';form.querySelector('[data-action=pump-remove]').hidden=true;if(state.shipmentDraft)state.shipmentDraft.pumpFile=null;}
 if(action==='pump-view'){const res=await fetch('/api/shipment-files/'+el.dataset.id,{headers:{Authorization:'Bearer '+state.token}});if(!res.ok)throw new Error((await res.json()).error);const url=URL.createObjectURL(await res.blob()),a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.download=el.dataset.name||'泵单';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
 if(action==='stock-flow'){const data=await api('/inventory/products/'+el.dataset.id+'/movements?'+stockQuery());modal(fullProductName(data.product)+' · 库存明细',stockMovements(data,{esc,num}),'<button data-action="close-modal">关闭</button>');}
 if(action==='stock-tab'){state.stockTab=el.dataset.value;render();}
 if(action==='stock-category'){state.inventoryCategory=el.dataset.value;state.stockVisible=30;render();}
 if(action==='stock-month'){state.stockRange={from:monthStart(state.boot.today),to:state.boot.today};await refresh();}
 if(action==='stock-more'){state.stockVisible+=30;render();}
 if(action==='shipment-new')openShipment(null);
 if(action==='shipment-edit')openShipment(state.shipments.find(s=>s.id===el.dataset.id));
 if(action==='shipment-add'||action==='shipment-remove'){const d=readShipment($('#shipment-form'),state);if(action==='shipment-add'){if(d.entries.length>=100)throw new Error('一次最多100种产品');d.entries.push({product:{id:''},quantity:''});}else d.entries.splice(Number(el.dataset.index),1);openShipment(d);}
 if(action==='shipment-void'){const s=state.shipments.find(s=>s.id===el.dataset.id);modal('作废发货清单',`<form id="shipment-void-form" data-id="${esc(s.id)}" data-version="${s.version}"><p>${esc(s.customer)} · ${s.date}</p>${field('作废原因','<input name="reason" required maxlength="300">')}<button class="primary" type="submit">确认作废</button></form>`,'<button data-action="close-modal">返回</button>');}
 if(['opening-new','opening-edit','stock-count'].includes(action)){const row=state.inventory.rows.find(r=>r.product.id===el.dataset.id)||state.inventory.rows.find(r=>r.product.category===state.inventoryCategory),kind=action==='stock-count'?'count':'opening';modal(kind==='count'?'登记实盘':'设置期初库存',stockEditor(state,row,kind,{esc,field,options}),'<button data-action="close-modal">返回</button>');}
 if(action==='stock-export'){const response=await fetch('/api/inventory/export?'+stockQuery(),{headers:{Authorization:'Bearer '+state.token}});if(!response.ok)throw new Error((await response.json()).error);const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download='发货与库存.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

 if(action==='review-mode'){state.batchReview=true;state.reviewSelection.clear();render();}
 if(action==='review-exit'){state.batchReview=false;state.reviewSelection.clear();render();}
 if(action==='review-all'){const pending=pendingReviews(state),all=state.reviewSelection.size===Math.min(pending.length,reviewLimit);state.reviewSelection.clear();if(!all)pending.slice(0,reviewLimit).forEach(r=>state.reviewSelection.set(r.id,r.version));syncReviewSelection(state);if(!all&&pending.length>reviewLimit)toast('已选择200条，可分批确认');}
 if(action==='approve-record'){try{await api('/records/'+el.dataset.id,{method:'PATCH',body:{action:'approve',version:Number(el.dataset.version)}});toast('已确认');await refresh();}catch(e){await refresh();throw e;}}
 if(action==='confirm-review-selection'){if(!state.reviewSelection.size)throw new Error('请先选择待确认记录');state.reviewBatch=[...state.reviewSelection].map(([id,version])=>({id,version}));modal('批量核对',reviewConfirmation(state,{esc,num}),'<button data-action="close-modal">取消</button><button class="primary" data-action="execute-review-batch">确认 '+state.reviewBatch.length+' 条</button>');}
 if(action==='execute-review-batch'){try{const r=await api('/records/approve-batch',{method:'POST',body:{records:state.reviewBatch}});closeModal();state.reviewSelection.clear();toast('已确认'+r.approvedCount+'条记录');await refresh();}catch(e){closeModal();await refresh();throw e;}}

 if(action==='delete-record')modal('删除未确认记录','<p>删除后该记录不再显示，操作历史会保留。</p>',`<button data-action="close-modal">取消</button><button class="danger" data-action="confirm-delete" data-id="${el.dataset.id}" data-version="${el.dataset.version}">确认删除</button>`);
 if(action==='confirm-delete'){await api('/records/'+el.dataset.id,{method:'DELETE',body:{version:Number(el.dataset.version)}});closeModal();toast('记录已删除');await navigate('records');}
 if(action==='wage-edit'){state.wageConfig=await api('/wages/config?month='+state.boot.today.slice(0,7));modal('工资单价与补助',wageEditor(state,{esc,num,field,options}),'<button data-action="close-modal">关闭</button>');}
 if(action==='send-code'){const phone=$('#phone').value;await api('/auth/code',{method:'POST',body:{phone}});startCodeCountdown(phone);$('#code-help').textContent='验证码已发送，有效期5分钟';}
 if(action==='navigate')await navigate(el.dataset.page);
 if(action==='period'){state.reviewSelection.clear();state.range=el.dataset.value;state.filters={category:state.filters.category||'',loadingOperation:state.filters.loadingOperation||''};await refresh();}
 if(action==='business'){const value=el.dataset.value,loading=['装车','卸车'].includes(value);state.filters={from:state.filters.from,to:state.filters.to,category:loading?'装/卸车':value,loadingOperation:loading?value:''};await refresh();}
 if(action==='material-products'){state.manage='products';state.manageCategory='浇注料';state.keyword='';await navigate('manage');}
 if(action==='manage-category'){state.manageCategory=el.dataset.value;state.keyword='';render();}
 if(action==='detail'){state.detail=null;state.page='detail';render();const r=await api('/records/'+el.dataset.id);state.detail=r.record;state.history=r.history;render();window.scrollTo(0,0);}
 if(action==='report-module'){if($('#report-form'))saveDraft($('#report-form'));if($('#bulk-report-form'))saveBulk(state,$('#bulk-report-form'));state.reportCategory=el.dataset.value;localStorage.setItem('report-module-'+state.user.id,state.reportCategory);resetBulkDefaults(state);render();}
 if(action==='report-loading'){if($('#report-form'))saveDraft($('#report-form'));if($('#bulk-report-form'))saveBulk(state,$('#bulk-report-form'));state.loadingOperation=el.dataset.value;localStorage.setItem('loading-operation-'+state.user.id,state.loadingOperation);resetBulkDefaults(state);render();}
 if(action==='quantity'){const form=$('#report-form');form.quantity.value=Math.max(0,Number(form.quantity.value||0)+Number(el.dataset.delta));saveDraft(form);updateReportWeight();}
 if(action==='submit-report'){const d=draft();d.mode=state.user.isLeader?'leader':'personal';d.workerId=d.workerId||state.user.id;d.entries=[{workerId:d.workerId,quantity:Number(d.quantity)}];await api(d.mode==='leader'?'/records/leader':'/records',{method:'POST',body:{...d,quantity:Number(d.quantity),entries:(d.entries||[]).map(e=>({...e,quantity:Number(e.quantity)}))}});localStorage.removeItem(draftKey());const old=JSON.parse(localStorage.getItem('draft-'+state.user.id)||'null');if(old&&state.boot.products.find(p=>p.id===old.productId)?.category===state.reportCategory)localStorage.removeItem('draft-'+state.user.id);closeModal();toast('已提交，产量和工资已更新');await navigate('report');}
 if(action==='approve'){await api('/records/'+state.detail.id,{method:'PATCH',body:{version:state.detail.version,action:'approve'}});toast('已确认');await navigate('records');}
 if(['reject','change-request','resolve-request'].includes(action))modal(action==='reject'?'退回给工人':action==='change-request'?'申请修改':'处理说明',`<form id="reason-form" data-kind="${action}" data-id="${esc(el.dataset.id||state.detail.id)}">${field('原因 / 说明','<textarea name="reason" rows="3" maxlength="300" required></textarea>')}<button class="primary" type="submit">提交</button></form>`,`<button data-action="close-modal">取消</button>`);
 if(action==='attendance'){await api('/attendance',{method:'PUT',body:{date:state.boot.today,status:el.dataset.status}});toast('已标记'+(el.dataset.status==='rest'?'休息':'停产'));}
 if(action==='clear-attendance'){await api('/attendance/'+state.boot.today,{method:'DELETE'});toast('已取消标记，可以填写产量');}
 if(action==='font'){const r=await api('/me',{method:'PATCH',body:{fontSize:Number(el.dataset.value)}});state.user=r.user;await refresh();}
 if(action==='logout'){closeModal();await api('/auth/logout',{method:'POST'});state.user=null;state.token=null;localStorage.removeItem('factory-token');document.documentElement.style.setProperty('--fs','22px');render();}
 if(action==='notices'){const r=await api('/notices');await api('/notices/read',{method:'POST'});modal('消息提醒',r.notices.map(n=>`<div class="history"><p>${esc(n.message)}</p><p class="small">${fmtTime(n.created_at)}</p>${n.record_id?`<button class="soft" data-action="notice-detail" data-id="${n.record_id}">查看记录</button>`:''}</div>`).join('')||'<p class="empty">暂无消息</p>','<button data-action="close-modal">关闭</button>');}
 if(action==='notice-detail'){closeModal();await act('detail',el);}
 if(action==='close-modal')closeModal();
 if(action==='refresh-detail'){const r=await api('/records/'+state.detail.id);state.detail=r.record;state.history=r.history;render();toast('记录已刷新');}
 if(action==='export'){const res=await fetch('/api/export?'+query(),{headers:{Authorization:'Bearer '+state.token}});if(!res.ok)throw new Error((await res.json()).error);const blob=await res.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='生产统计.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('报表已导出');}
 if(action==='history-open'){state.importPreview=await api('/imports/'+el.dataset.id);state.importSelection=new Set();state.importOffset=0;render();}if(action==='history-refresh'){state.importPreview=await api('/imports/'+state.importPreview.id);state.importSelection=new Set();render();}if(action==='history-select-ready'){state.importSelection=new Set(state.importPreview.entries.filter(e=>e.ready&&!e.recordId).map(e=>e.sourceRef));render();}if(action==='history-clear-selection'){state.importSelection=new Set();render();}if(action==='history-page'){state.importOffset=Number(el.dataset.offset);render();window.scrollTo(0,0);}if(action==='manage-tab'){if(!manageTabs(state.user).some(t=>t[0]===el.dataset.value))throw new Error('没有此管理权限');state.manage=el.dataset.value;state.keyword='';await refresh();}
 if(action==='manage-edit')openManagement(el.dataset.id);
 if(action==='refresh-permissions'){await refresh();toast('权限已刷新');}
 if(action==='admin-new'){modal('新增管理员',adminEditor({esc,field}),'<button data-action="close-modal">取消</button>');}
 if(action==='admin-delete'){const user=state.admins.find(u=>u.id===el.dataset.id);if(!user||user.isSuperAdmin)throw new Error('总管理员账号不可删除');modal('删除管理员',`<p>确认删除 ${esc(user.name)}（${esc(user.phone)}）？</p><p class="small note">删除后移出管理员名单，立即失去登录和操作权限。历史数据保留。</p>`,`<button data-action="close-modal">取消</button><button class="danger" data-action="admin-delete-confirm" data-id="${esc(user.id)}">确认删除</button>`);}
 if(action==='admin-delete-confirm'){await api('/admins/'+el.dataset.id,{method:'DELETE'});closeModal();await refresh();toast('管理员已删除');}
 if(action==='permission-edit'){const user=state.admins.find(u=>u.id===el.dataset.id);modal('设置管理员权限',permissionEditor(user,state.boot.permissionCatalog,{esc}),'<button data-action="close-modal">取消</button>');}
}
function openManagement(id){const isUser=state.manage==='users',old=(isUser?state.users:state.boot.products).find(x=>x.id===id)||{},b=state.boot;let body=isUser?`${field('姓名',`<input name="name" value="${esc(old.name)}" required maxlength="30">`)}${field('手机号',`<input name="phone" value="${esc(old.phone)}" inputmode="tel" maxlength="11" placeholder="待管理员绑定（可先保存名册）">`)}${field('身份',`<select name="role"><option value="worker">工人</option>${state.user.isSuperAdmin?`<option value="admin" ${old.role==='admin'?'selected':''}>管理员</option>`:''}</select>`)}${field('默认预制块班组 / 组长负责班组',`<select name="groupId"><option value="">未设置默认班组</option>${options(b.groups.filter(g=>!['g4','g5'].includes(g.id)),old.groupId)}</select>`)}<label class="check-line"><input type="checkbox" name="isLeader" ${old.isLeader?'checked':''}>组长，可给组员批量填写</label>`:`${field('产品名称',`<input name="name" value="${esc(old.name)}" required maxlength="100">`)}${field('规格',`<input name="spec" value="${esc(old.spec)}" maxlength="100">`)}${field('分类',`<select name="category">${['预制块','浇注料','装/卸车'].map(v=>`<option ${v===old.category?'selected':''}>${v}</option>`).join('')}</select>`)}${field('单位',`<input name="unit" value="${esc(old.unit)}" placeholder="例如：块、公斤、吨、袋" maxlength="10">`)}${field('数量小数位数',`<select name="precision">${[0,1,2,3].map(v=>`<option ${v===old.precision?'selected':''}>${v}</option>`).join('')}</select>`)}${field('每个单位重量（公斤，可不填）',`<input name="weightKg" type="number" min="0.001" step="any" value="${esc(old.weightKg??'')}">`)}${field('所属班组',`<select name="groupId"><option value="">全厂通用</option>${options(b.groups,old.groupId)}</select>`)}`;modal((id?'编辑':'新增')+(isUser?'员工':'产品'),`<form id="manage-form" data-id="${esc(id||'')}" data-kind="${state.manage}">${body}<label class="check-line"><input type="checkbox" name="active" ${old.active!==false?'checked':''}>启用</label>${isUser?`<label class="check-line"><input type="checkbox" name="expected" ${old.expected!==false?'checked':''}>每天需要填写</label>`:''}<button class="primary" type="submit">保存</button></form>`,'<button data-action="close-modal">取消</button>');}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||state.busy||state.pumpUploading)return;state.busy=true;el.disabled=true;try{await act(el.dataset.action,el);}catch(e){toast(e.message);}finally{state.busy=false;el.disabled=false;updateCodeButton();}});
document.addEventListener('submit',async event=>{event.preventDefault();if(state.busy||state.pumpUploading)return;const form=event.target,data=Object.fromEntries(new FormData(form));state.busy=true;const button=form.querySelector('[type=submit]');if(button)button.disabled=true;try{

 if(form.id==='worker-range-form'){if(data.from>data.to)throw new Error('开始日期不能晚于结束日期');state.filters={from:data.from,to:data.to};await refresh();}
 if(form.id==='bulk-report-form'){const d=saveBulk(state,form);if(d.entries.some(e=>!e.productId||!e.workerId||!Number.isFinite(Number(e.quantity))||Number(e.quantity)<=0))throw new Error('请选择每行的项目/产品并输入生产量');state.bulkSubmission=d;modal('确认批量填写',bulkConfirmation(state,d,{esc,num}),'<button data-action="close-modal">返回修改</button><button class="primary" data-action="submit-bulk-report">确认提交</button>');}
 if(form.id==='stock-date-form'){state.stockRange={from:data.date,to:data.date};await refresh();}
 if(form.id==='stocktake-search-form'){state.stocktakeKeyword=data.keyword;render();}
 if(form.id==='stock-search-form'){state.stockKeyword=data.keyword;state.stockVisible=30;render();}
 if(form.id==='shipment-form'){const d=readShipment(form,state);await api('/shipments'+(d.id?'/'+d.id:''),{method:d.id?'PATCH':'POST',body:{...d,entries:d.entries.map(e=>({productId:e.productId,quantity:Number(e.quantity)}))}});closeModal();await refresh();toast('发货已保存，库存同步更新');}
 if(form.id==='shipment-void-form'){await api('/shipments/'+form.dataset.id,{method:'DELETE',body:{version:Number(form.dataset.version),reason:data.reason}});closeModal();await refresh();toast('发货已作废');}
 if(form.id==='stock-opening-form'||form.id==='stock-count-form'){await api('/inventory/'+(form.id==='stock-opening-form'?'opening':'count'),{method:'PUT',body:{...data,quantity:Number(data.quantity),version:Number(form.dataset.version)}});closeModal();await refresh();toast('库存已更新');}
 if(form.id==='template-export'){const res=await fetch('/api/export-template?'+new URLSearchParams(data),{headers:{Authorization:'Bearer '+state.token}});if(!res.ok)throw new Error((await res.json()).error);const url=URL.createObjectURL(await res.blob()),a=document.createElement('a');a.href=url;a.download=data.month+data.category+'记工表.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('月报已导出');}
 if(form.id==='history-upload'){const file=form.elements.file.files[0];if(file.size>9e6)throw new Error('表格超过大小限制');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});state.importPreview=await api('/imports/preview',{method:'POST',body:{category:data.category,month:data.month,fileName:file.name,base64}});state.importSelection=new Set();state.importOffset=0;state.imports=(await api('/imports')).imports;render();}
 if(form.id==='history-commit'){if(!state.importSelection?.size)throw new Error('请选择已核准记录');await api('/imports/'+state.importPreview.id+'/commit',{method:'POST',body:{confirmed:form.elements.confirmed.checked,sourceRefs:[...state.importSelection]}});state.importPreview=await api('/imports/'+state.importPreview.id);state.importSelection=new Set();state.imports=(await api('/imports')).imports;render();toast('历史数据已核准导入');}
 if(form.id==='login-form')await login(data.phone,data.code);
 if(form.id==='filter-form'){state.reviewSelection.clear();const loading=['装车','卸车'].includes(data.category);state.filters={...data,category:state.page==='home'?state.filters.category:loading?'装/卸车':data.category,loadingOperation:state.page==='home'?state.filters.loadingOperation:loading?data.category:''};await refresh();}
 if(form.id==='report-form'){const d=saveDraft(form),p=state.boot.products.find(p=>p.id===d.productId);if(!p)throw new Error('请先选择产品');if(!Number.isFinite(Number(d.quantity))||Number(d.quantity)<=0)throw new Error('请输入大于0的生产量');modal('确认填写',detail('日期',d.date)+detail('产品',fullProductName(p))+detail('姓名',state.boot.workers.find(u=>u.id===d.workerId)?.name||state.user.name)+detail('生产量',num(d.quantity)+p.unit)+detail('填写人',state.user.name),`<button data-action="close-modal">返回修改</button><button class="primary" data-action="submit-report">确认提交</button>`);}
 if(form.id==='correction-form'){const r=state.detail;await api('/records/'+r.id,{method:'PATCH',body:{action:state.user.role==='admin'?'correct':'worker_edit',version:r.version,...(state.user.role==='admin'?{...data,memberIds:new FormData(form).getAll('memberIds')}:{}),quantity:Number(data.quantity),reason:data.reason}});toast('已保存，产量和工资同步更新');await navigate('records');}
 if(form.id==='reason-form'){if(form.dataset.kind==='reject')await api('/records/'+form.dataset.id,{method:'PATCH',body:{action:'reject',version:state.detail.version,reason:data.reason}});else if(form.dataset.kind==='resolve-request')await api('/change-requests/'+form.dataset.id,{method:'PATCH',body:{reason:data.reason}});else await api('/records/'+form.dataset.id+'/change-requests',{method:'POST',body:{reason:data.reason}});closeModal();toast('已提交');await refresh();}
 if(form.id==='wage-policy-form'){await api('/wages/policy',{method:'PUT',body:{effectiveDate:data.effectiveDate,precastMode:data.precastMode,precastRate:Number(data.precastRate),materialMultiplier:data.materialMultiplier===''?null:Number(data.materialMultiplier),supplementsConfirmed:form.supplementsConfirmed.checked}});closeModal();await refresh();toast('工资规则已保存');}
 if(form.id==='wage-rate-form'){await api('/wages/rates',{method:'PUT',body:{productId:data.productId,effectiveDate:data.effectiveDate,rate:Number(data.rate),basis:data.basis}});closeModal();await refresh();toast('单价已保存，应用日期起的工资已重算');}
 if(form.id==='wage-adjust-form'){await api('/wages/adjustments',{method:'PUT',body:{workerId:data.workerId,date:data.date,amount:Number(data.amount),reason:data.reason}});closeModal();await refresh();toast('补助调整已保存');}
 if(form.id==='admin-create-form'){await api('/admins',{method:'POST',body:{name:data.name,phone:data.phone}});closeModal();await refresh();toast('管理员已新增，请设置权限');}
 if(form.id==='permission-form'){await api('/admins/'+form.dataset.id+'/permissions',{method:'PATCH',body:{permissions:new FormData(form).getAll('permissions')}});closeModal();await refresh();toast('权限已保存，立即生效');}
 if(form.id==='search-form'){state.keyword=data.keyword;render();}
 if(form.id==='manage-form'){const isUser=form.dataset.kind==='users';data.active=form.active.checked;if(isUser){data.expected=form.expected.checked;data.isLeader=form.isLeader.checked;}else{data.precision=Number(data.precision);data.weightKg=data.weightKg===''?null:Number(data.weightKg);}await api('/'+form.dataset.kind+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PATCH':'POST',body:data});closeModal();toast('已保存');if(isUser)state.users=(await api('/users')).users;await refresh();}
 }catch(e){toast(e.message);}finally{state.busy=false;if(button)button.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.closest('#bulk-report-form')){saveBulk(state,$('#bulk-report-form'));const row=e.target.closest('[data-bulk-row]');if(row)updateBulkWeight(state,row);}if(e.target.id==='phone')updateCodeButton(state.busy);if(e.target.closest('#report-form')){saveDraft($('#report-form'));if(!['report-worker','report-group'].includes(e.target.id))updateReportWeight();}if(e.target.id==='edit-quantity'){const r=state.detail,q=Number(e.target.value),productId=$('#edit-product')?.value,p=productId&&productId!==r.product.id?state.boot.products.find(p=>p.id===productId):r.product;$('#edit-weight').textContent=p.weightKg?num(q*p.weightKg/1000)+' 吨':p.unit==='公斤'?num(q/1000)+' 吨':p.unit==='吨'?num(q)+' 吨':'按 '+p.unit+' 统计';}});
document.addEventListener('change',e=>{if(e.target.id==='stock-query-date'){state.stockRange={from:e.target.value,to:e.target.value};refresh().catch(e=>toast(e.message));}if(e.target.id==='admin-report-date'){state.reportDate=e.target.value;refresh().catch(e=>toast(e.message));}if(e.target.id==='admin-report-group'){state.reportGroup=e.target.value;refresh().catch(e=>toast(e.message));}if(e.target.id==='worker-summary-date'){state.range='day';state.filters={from:e.target.value,to:e.target.value};refresh().catch(e=>toast(e.message));}if(e.target.id==='stock-setting-product')updateStockSetting();if(e.target.closest('#bulk-report-form')){const d=saveBulk(state,$('#bulk-report-form'));if(e.target.id==='bulk-group'){d.entries=d.entries.map(e=>({...e,productId:'',quantity:''}));localStorage.setItem(bulkKey(state),JSON.stringify(d));render();}else if(e.target.hasAttribute('data-bulk-product')){const p=state.boot.products.find(p=>p.id===e.target.value),row=e.target.closest('[data-bulk-row]'),input=row.querySelector('[data-bulk-quantity]');input.step=p?10**-p.precision:1;input.min=input.step;row.querySelector('.input-unit').textContent=p?.unit||'';updateBulkWeight(state,row);}}if(e.target.hasAttribute('data-shipment-product')){const p=state.boot.products.find(p=>p.id===e.target.value),row=e.target.closest('[data-shipment-row]');row.querySelector('[data-shipment-quantity]').step=p?10**-p.precision:1;row.querySelector('[data-shipment-quantity]').min=p?10**-p.precision:1;row.querySelector('.input-unit').textContent=p?.unit||'';}if(e.target.dataset.reviewRecord){if(state.busy){syncReviewSelection(state);return;}if(e.target.checked){if(state.reviewSelection.size>=reviewLimit){e.target.checked=false;toast('每次最多确认200条');return;}state.reviewSelection.set(e.target.dataset.reviewRecord,Number(e.target.dataset.version));}else state.reviewSelection.delete(e.target.dataset.reviewRecord);syncReviewSelection(state);}if(e.target.name==='sourceRefs'){state.importSelection=state.importSelection||new Set();if(e.target.checked)state.importSelection.add(e.target.value);else state.importSelection.delete(e.target.value);}if(e.target.name==='workerIds'){const q=$('[data-worker-quantity=\"'+e.target.value+'\"]');q.disabled=!e.target.checked;q.required=e.target.checked;}if(e.target.id==='edit-product'){const p=state.boot.products.find(p=>p.id===e.target.value),form=$('#correction-form');if(p?.groupId)form.elements.groupId.value=p.groupId;form.quantity.step=10**-(p?.precision||0);form.quantity.dispatchEvent(new Event('input',{bubbles:true}));syncDropdowns(form);}if(e.target.closest('#report-form')){saveDraft($('#report-form'));if(['report-mode','report-group'].includes(e.target.id))render();else updateReportWeight();}});

try{state.config=await api('/config');if(state.token){state.boot=await api('/bootstrap');state.user=state.boot.user;state.page=defaultPage(state.user);state.reportCategory=localStorage.getItem('report-module-'+state.user.id)||'浇注料';state.loadingOperation=loadingPreference();await refresh();}else render();}catch(e){render();if(e.status!==401)toast('连接服务失败：'+e.message);}

function refreshLiveView(){if(state.token&&!state.busy&&document.visibilityState==='visible'&&!$('#dialog')?.open&&['home','records','inventory'].includes(state.page)&&!document.activeElement?.matches('input,textarea,select')&&!document.querySelector('details[open],.nice-select.open')){state.busy=true;refresh().catch(e=>toast(e.message)).finally(()=>state.busy=false);}}
setInterval(refreshLiveView,30000);window.addEventListener('focus',refreshLiveView);

async function uploadPump(file){
 if(!file)return;if(file.size>6*1024*1024)throw new Error('泵单不能超过6MB');
 const form=$('#shipment-form'),submit=form.querySelector('button[type="submit"]');state.pumpUploading=true;submit.disabled=true;$('#pump-file-info').textContent='正在上传…';
 try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('读取文件失败'));reader.readAsDataURL(file);});const r=await api('/shipment-files',{method:'POST',body:{name:file.name,base64}});form.elements.pumpFileId.value=r.file.id;$('#pump-file-info').textContent=r.file.name;form.querySelector('[data-action=pump-remove]').hidden=false;state.shipmentDraft={...state.shipmentDraft,pumpFile:r.file};}catch(e){$('#pump-file-info').textContent='上传失败，请重试';throw e;}finally{state.pumpUploading=false;submit.disabled=false;}
}
document.addEventListener('change',e=>{if(['pump-camera','pump-choose'].includes(e.target.id))uploadPump(e.target.files[0]).catch(e=>toast(e.message));});
